<script setup lang="ts">import { SelectContent,SelectRoot,SelectTrigger } from '@fex-design/vue/primitive/select'; const options=[{value:'react',label:'React'},{value:'vue',label:'Vue'},{value:'solid',label:'Solid'}]; const filter=(keyword:string,option:{label:string})=>{let from=0;return [...keyword.toLowerCase()].every(character=>{const index=option.label.toLowerCase().indexOf(character,from);from=index+1;return index>=0})}</script><template><SelectRoot :options="options" show-search :filter-option="filter"><SelectTrigger class="w-72" placeholder="输入 rt 试试"/><SelectContent/></SelectRoot></template>
